const body = $json.body ?? $json;
const trials = Array.isArray(body.trials) ? body.trials : [];

const trialCount = trials.length;
const correctCount = trials.filter((trial) => Number(trial.Correct ?? trial.correct ?? 0) === 1).length;
const totalErrors = trials.reduce((sum, trial) => sum + Number(trial.Errors ?? trial.errors ?? 0), 0);
const totalMissed = trials.reduce((sum, trial) => sum + Number(trial.Missed_Targets ?? trial.missed_targets ?? 0), 0);
const avgReaction = trialCount > 0 ? trials.reduce((sum, trial) => sum + Number(trial.Reaction_Time_ms ?? trial.reaction_time_ms ?? 0), 0) / trialCount : 0;
const weakSkills = [...new Set(trials.filter((trial) => Number(trial.Errors ?? trial.errors ?? 0) > 0 || Number(trial.Missed_Targets ?? trial.missed_targets ?? 0) > 0).map((trial) => trial.Task_Type ?? trial.task_type).filter(Boolean))];

const accuracy = trialCount > 0 ? (correctCount / trialCount) * 100 : 0;
let status = 'normal';
let label = 'Normal Child';
let confidence = Math.min(0.98, Math.max(0.55, accuracy / 100));

if (trialCount === 0) {
  confidence = 0;
} else if (accuracy < 60 || totalErrors >= Math.max(3, Math.ceil(trialCount / 2)) || totalMissed >= Math.max(2, Math.ceil(trialCount / 3)) || avgReaction > 2500) {
  status = 'disorder';
  label = 'Visual Perception Disorder Detected';
  confidence = Math.min(0.97, Math.max(0.65, 1 - accuracy / 100 + Math.min(totalErrors * 0.03, 0.15)));
}

const probDisorder = status === 'disorder' ? confidence : Math.max(0.02, 1 - confidence);
const probNormal = status === 'normal' ? confidence : Math.max(0.02, 1 - confidence);
const trainingPlan = status === 'disorder' ? ['Play visual tracking games for 10 minutes daily.', 'Repeat matching exercises with fewer distractions.', 'Monitor progress over the next 7 days.'] : ['Keep playing a mix of matching and tracking games.', 'Increase difficulty gradually to maintain progress.'];

return [{json: {status, label, confidence: Number(confidence.toFixed(4)), prob_normal: Number(probNormal.toFixed(4)), prob_disorder: Number(probDisorder.toFixed(4)), weak_skills: weakSkills, training_plan: trainingPlan, trials_count: trialCount, model_version: 'n8n-rule-v1', metrics: {accuracy: Number(accuracy.toFixed(2)), correct_count: correctCount, errors_count: totalErrors, missed_count: totalMissed, avg_reaction_time_ms: Number(avgReaction.toFixed(2))}}}];
